using System.Text.Json;
using LXST;

namespace Sideband.Tests;

// Generated by SidebandVoiceGenerateVectors.py against actual primary 2.2.0
// d069122af14880e43607aed0b71add4c7806fbe0; source digests/method are in the fixture.
[Trait("Category", "Unit")]
public sealed class SidebandVoicePolicyTests
{
    private const string Peer = "000102030405060708090a0b0c0d0e0f";

    [Fact]
    public void DefaultsConstantsAndStateNumbersMatchExecutedPrimary()
    {
        using var fixture = ReadFixture();
        var defaults = fixture.RootElement.GetProperty("defaults");
        var config = new SidebandVoiceConfiguration();
        Assert.Equal(defaults.GetProperty("voice_trusted_only").GetBoolean(), config.TrustedOnly);
        Assert.Equal(defaults.GetProperty("voice_hdx_direct_ptt").GetBoolean(), config.DirectPushToTalk);
        Assert.Equal(defaults.GetProperty("voice_hdx_loudspeaker").GetBoolean(), config.HalfDuplexLoudspeaker);
        Assert.Null(config.Speaker);
        Assert.Null(config.Microphone);
        Assert.Null(config.Loudspeaker);
        Assert.Null(config.Ringer);
        var constants = fixture.RootElement.GetProperty("constants");
        Assert.Equal(constants.GetProperty("RING_TIME").GetInt32(), SidebandVoiceService.RingTimeout.TotalSeconds);
        Assert.Equal(constants.GetProperty("WAIT_TIME").GetInt32(), SidebandVoiceService.WaitTimeout.TotalSeconds);
        Assert.Equal(constants.GetProperty("PATH_TIME").GetInt32(), SidebandVoiceService.PathTimeout.TotalSeconds);
        Assert.Equal(constants.GetProperty("CALL_LOG_KEEP").GetInt32(), SidebandVoiceService.CallLogRetention.TotalSeconds);
        foreach (var (name, state) in new[] { ("STATE_AVAILABLE", SidebandVoiceState.Available),
            ("STATE_CONNECTING", SidebandVoiceState.Connecting), ("STATE_RINGING", SidebandVoiceState.Ringing),
            ("STATE_IN_CALL", SidebandVoiceState.InCall) })
            Assert.Equal(constants.GetProperty(name).GetInt32(), (int)state);
        Assert.Equal("d069122af14880e43607aed0b71add4c7806fbe0", fixture.RootElement.GetProperty("sideband_sha").GetString());
        Assert.Equal("51e61510ea5eee832e7b9ad452459998c76561d970e0e773a253fe17cc7f2ab8",
            fixture.RootElement.GetProperty("source_sha256").GetProperty("sbapp/sideband/voice.py").GetString());
        var ringer = fixture.RootElement.GetProperty("ringer");
        Assert.Equal(ringer.GetProperty("initial_delay_seconds").GetDouble(), SidebandVoiceService.RingerDelay.TotalSeconds);
        foreach (var observation in ringer.GetProperty("observations").EnumerateArray())
        {
            Assert.False(observation.GetProperty("started_before_400ms").GetBoolean());
            Assert.Equal(observation.GetProperty("incoming").GetBoolean() && !observation.GetProperty("early_answer").GetBoolean(),
                observation.GetProperty("started").GetBoolean());
            Assert.True(observation.GetProperty("stopped").GetBoolean());
        }
    }

    [Fact]
    public void ExecutedPrimaryCallHistoryReloadsAndClearPersistsAnEmptyMessagePackArray()
    {
        using var fixture = ReadFixture();
        var log = fixture.RootElement.GetProperty("call_log");
        Assert.Empty(log.GetProperty("initial").EnumerateArray());
        var before = log.GetProperty("before_restart").EnumerateArray().ToArray();
        var restarted = log.GetProperty("restart_loaded").EnumerateArray().ToArray();
        string[] events = ["outgoing-success", "ongoing-ended", "incoming-success",
            "outgoing-failure", "incoming-missed"];
        Assert.Equal(events.Length, before.Length);
        Assert.Equal(events.Length, restarted.Length);
        var results = log.GetProperty("log_results").EnumerateArray().ToArray();
        Assert.Equal(events.Length, results.Length);
        Assert.All(results, result => Assert.Equal(JsonValueKind.Null, result.ValueKind));
        for (var index = 0; index < events.Length; index++)
        {
            var value = new SidebandVoiceCallEvent(
                DateTimeOffset.UnixEpoch.AddSeconds(restarted[index].GetProperty("time").GetDouble()),
                restarted[index].GetProperty("event").GetString()!,
                restarted[index].GetProperty("identity").GetString()!);
            Assert.Equal(events[index], value.Event);
            Assert.Equal(Peer, value.IdentityHash);
            Assert.Equal(1800000000L + index, value.Time.ToUnixTimeSeconds());
            Assert.Equal(before[index].GetRawText(), restarted[index].GetRawText());
        }
        Assert.Equal(JsonValueKind.Null, log.GetProperty("clear_result").ValueKind);
        Assert.Equal("90", log.GetProperty("packed_empty_hex").GetString());
        Assert.Empty(log.GetProperty("after_clear").EnumerateArray());
        Assert.Empty(log.GetProperty("restart_after_clear").EnumerateArray());
    }

    [Fact]
    public void AuthorizationUsesDeliveryConversationPrecedenceNotAUnionOfTrust()
    {
        using var fixture = ReadFixture();
        foreach (var row in fixture.RootElement.GetProperty("policies").EnumerateArray())
        {
            var value = row.GetProperty("delivery_trust");
            bool? delivery = value.ValueKind == JsonValueKind.Null ? null : value.GetBoolean();
            var policy = new SidebandVoicePolicy(new() { TrustedOnly = row.GetProperty("trusted_only").GetBoolean() },
                [new(Peer, delivery, row.GetProperty("voice_trust").GetBoolean())]);
            Assert.Equal(row.GetProperty("allowed").GetBoolean(), policy.IsAllowed(Peer.ToUpperInvariant()));
        }
        Assert.False(new SidebandVoicePolicy(new() { TrustedOnly = true }).IsAllowed(Peer));
    }

    [Fact]
    public void DirectPttRequiresExplicitOwnerFlagAndTrustedPttEnabledDeliveryConversation()
    {
        using var fixture = ReadFixture();
        foreach (var row in fixture.RootElement.GetProperty("direct_ptt").EnumerateArray())
        {
            var policy = new SidebandVoicePolicy(new() { DirectPushToTalk = row.GetProperty("enabled").GetBoolean() },
                [new(Peer, row.GetProperty("delivery_trusted").GetBoolean(), true, row.GetProperty("ptt_enabled").GetBoolean())]);
            Assert.Equal(row.GetProperty("allowed").GetBoolean(), policy.AllowsDirectPushToTalk(Peer));
        }
        Assert.False(new SidebandVoicePolicy(new() { DirectPushToTalk = true },
            [new(Peer, null, true, true)]).AllowsDirectPushToTalk(Peer));
    }

    [Fact]
    public void PolicySnapshotsItsInputAndRejectsAmbiguousIdentityKeys()
    {
        var peers = new List<SidebandVoicePeer> { new(Peer, true) };
        var policy = new SidebandVoicePolicy(new() { TrustedOnly = true }, peers);
        peers.Clear();
        Assert.True(policy.IsAllowed(Peer));
        Assert.Throws<ArgumentException>(() => new SidebandVoicePolicy(peers: [new("bad")]));
        Assert.Throws<ArgumentException>(() => new SidebandVoicePolicy(peers: [new(new string('z', 32))]));
        Assert.Throws<ArgumentException>(() => new SidebandVoicePolicy(peers: [new(Peer), new(Peer.ToUpperInvariant())]));
    }

    [Fact]
    public void DeliverySnapshotsAuthorizeAnUnannouncedIdentityAndPreserveReferencePrecedence()
    {
        using var fixture = ReadFixture();
        var vector = fixture.RootElement.GetProperty("destination_vector");
        var identity = vector.GetProperty("identity").GetString()!;
        var destination = vector.GetProperty("delivery").GetString()!;
        foreach (var row in fixture.RootElement.GetProperty("policies").EnumerateArray())
        {
            var value = row.GetProperty("delivery_trust");
            var conversations = value.ValueKind == JsonValueKind.Null
                ? Array.Empty<SidebandVoiceDeliveryPeer>()
                : [new SidebandVoiceDeliveryPeer(destination, value.GetBoolean())];
            var policy = new SidebandVoicePolicy(new() { TrustedOnly = row.GetProperty("trusted_only").GetBoolean() },
                [new(identity, VoiceTrusted: row.GetProperty("voice_trust").GetBoolean())], conversations);
            Assert.Equal(row.GetProperty("allowed").GetBoolean(), policy.IsAllowed(identity));
        }
        var deliveries = new List<SidebandVoiceDeliveryPeer> { new(destination, true, true) };
        var imported = new SidebandVoicePolicy(new() { TrustedOnly = true, DirectPushToTalk = true }, deliveryPeers: deliveries);
        deliveries.Clear();
        Assert.True(imported.IsAllowed(identity));
        Assert.True(imported.AllowsDirectPushToTalk(identity));
        var untrusted = new SidebandVoicePolicy(new() { TrustedOnly = true, DirectPushToTalk = true },
            [new(identity, true, true, true)], [new(destination, false, true)]);
        Assert.False(untrusted.IsAllowed(identity));
        Assert.False(untrusted.AllowsDirectPushToTalk(identity));
        Assert.Throws<ArgumentException>(() => new SidebandVoicePolicy(deliveryPeers: [new("bad", true)]));
        Assert.Throws<ArgumentException>(() => new SidebandVoicePolicy(deliveryPeers:
            [new(destination, true), new(destination.ToUpperInvariant(), false)]));
    }

    private static JsonDocument ReadFixture() => JsonDocument.Parse(File.ReadAllText(
        Path.Combine(AppContext.BaseDirectory, "Fixtures", "sideband-voice.json")));
}
